# MAGIC <span style="color: #FF7B72">COMMENT</span><span style="color: #6E7681"> </span><span style="color: #A5D6FF">'Raw orders'</span>
# MAGIC <span style="color: #FF7B72">AS</span><span style="color: #6E7681"> </span><span style="color: #FF7B72">SELECT</span><span style="color: #6E7681"> </span><span style="color: #FF7B72; font-weight: bold">*</span><span style="color: #E6EDF3">,</span><span style="color: #6E7681"> </span><span style="color: #E6EDF3">_metadata.file_name</span><span style="color: #6E7681"> </span><span style="color: #FF7B72">AS</span><span style="color: #6E7681"> </span><span style="color: #E6EDF3">source_file,</span><span style="color: #6E7681"> </span><span style="color: #FF7B72">current_timestamp</span><span style="color: #E6EDF3">()</span><span style="color: #6E7681"> </span><span style="color: #FF7B72">AS</span><span style="color: #6E7681"> </span><span style="color: #E6EDF3">ingested_at</span>
# MAGIC <span style="color: #FF7B72">FROM</span><span style="color: #6E7681"> </span><span style="color: #E6EDF3">STREAM</span><span style="color: #6E7681"> </span><span style="color: #E6EDF3">read_files(</span><span style="color: #A5D6FF">'/Volumes/shop/raw/orders/'</span><span style="color: #E6EDF3">,</span><span style="color: #6E7681"> </span><span style="color: #E6EDF3">format</span><span style="color: #6E7681"> </span><span style="color: #FF7B72; font-weight: bold">=&gt;</span><span style="color: #6E7681"> </span><span style="color: #A5D6FF">'json'</span><span style="color: #E6EDF3">);</span>
# MAGIC <span></span>
# MAGIC <span style="color: #8B949E; font-style: italic">-- Silver: clean + data quality</span>
# MAGIC <span style="color: #FF7B72">CREATE</span><span style="color: #6E7681"> </span><span style="color: #FF7B72">OR</span><span style="color: #6E7681"> </span><span style="color: #E6EDF3">REFRESH</span><span style="color: #6E7681"> </span><span style="color: #E6EDF3">STREAMING</span><span style="color: #6E7681"> </span><span style="color: #FF7B72">TABLE</span><span style="color: #6E7681"> </span><span style="color: #E6EDF3">orders_silver</span><span style="color: #6E7681"> </span><span style="color: #E6EDF3">(</span>
# MAGIC <span style="color: #6E7681">  </span><span style="color: #FF7B72">CONSTRAINT</span><span style="color: #6E7681"> </span><span style="color: #E6EDF3">valid_id</span><span style="color: #6E7681">     </span><span style="color: #E6EDF3">EXPECT</span><span style="color: #6E7681"> </span><span style="color: #E6EDF3">(order_id</span><span style="color: #6E7681"> </span><span style="color: #FF7B72">IS</span><span style="color: #6E7681"> </span><span style="color: #FF7B72">NOT</span><span style="color: #6E7681"> </span><span style="color: #FF7B72">NULL</span><span style="color: #E6EDF3">)</span><span style="color: #6E7681"> </span><span style="color: #FF7B72">ON</span><span style="color: #6E7681"> </span><span style="color: #E6EDF3">VIOLATION</span><span style="color: #6E7681"> </span><span style="color: #FF7B72">DROP</span><span style="color: #6E7681"> </span><span style="color: #FF7B72">ROW</span><span style="color: #E6EDF3">,</span>
# MAGIC <span style="color: #6E7681">  </span><span style="color: #FF7B72">CONSTRAINT</span><span style="color: #6E7681"> </span><span style="color: #E6EDF3">positive_amt</span><span style="color: #6E7681"> </span><span style="color: #E6EDF3">EXPECT</span><span style="color: #6E7681"> </span><span style="color: #E6EDF3">(amount</span><span style="color: #6E7681"> </span><span style="color: #FF7B72; font-weight: bold">&gt;</span><span style="color: #6E7681"> </span><span style="color: #A5D6FF">0</span><span style="color: #E6EDF3">)</span><span style="color: #6E7681">           </span><span style="color: #FF7B72">ON</span><span style="color: #6E7681"> </span><span style="color: #E6EDF3">VIOLATION</span><span style="color: #6E7681"> </span><span style="color: #E6EDF3">FAIL</span><span style="color: #6E7681"> </span><span style="color: #FF7B72">UPDATE</span><span style="color: #E6EDF3">,</span>
