# MAGIC <span style="color: #E6EDF3">)</span>
# MAGIC <span style="color: #FF7B72">AS</span><span style="color: #6E7681"> </span><span style="color: #FF7B72">SELECT</span><span style="color: #6E7681"> </span><span style="color: #E6EDF3">order_id,</span><span style="color: #6E7681"> </span><span style="color: #FF7B72">lower</span><span style="color: #E6EDF3">(email)</span><span style="color: #6E7681"> </span><span style="color: #FF7B72">AS</span><span style="color: #6E7681"> </span><span style="color: #E6EDF3">email,</span><span style="color: #6E7681"> </span><span style="color: #FF7B72">CAST</span><span style="color: #E6EDF3">(amount</span><span style="color: #6E7681"> </span><span style="color: #FF7B72">AS</span><span style="color: #6E7681"> </span><span style="color: #E6EDF3">DECIMAL(</span><span style="color: #A5D6FF">10</span><span style="color: #E6EDF3">,</span><span style="color: #A5D6FF">2</span><span style="color: #E6EDF3">))</span><span style="color: #6E7681"> </span><span style="color: #FF7B72">AS</span><span style="color: #6E7681"> </span><span style="color: #E6EDF3">amount,</span>
# MAGIC <span style="color: #6E7681">          </span><span style="color: #FF7B72">CAST</span><span style="color: #E6EDF3">(order_ts</span><span style="color: #6E7681"> </span><span style="color: #FF7B72">AS</span><span style="color: #6E7681"> </span><span style="color: #FF7B72">TIMESTAMP</span><span style="color: #E6EDF3">)</span><span style="color: #6E7681"> </span><span style="color: #FF7B72">AS</span><span style="color: #6E7681"> </span><span style="color: #E6EDF3">order_ts</span>
# MAGIC <span style="color: #FF7B72">FROM</span><span style="color: #6E7681"> </span><span style="color: #E6EDF3">STREAM(orders_bronze);</span>
# MAGIC <span></span>
# MAGIC <span style="color: #8B949E; font-style: italic">-- Gold: aggregate for BI</span>
# MAGIC <span style="color: #FF7B72">CREATE</span><span style="color: #6E7681"> </span><span style="color: #FF7B72">OR</span><span style="color: #6E7681"> </span><span style="color: #E6EDF3">REFRESH</span><span style="color: #6E7681"> </span><span style="color: #E6EDF3">MATERIALIZED</span><span style="color: #6E7681"> </span><span style="color: #FF7B72">VIEW</span><span style="color: #6E7681"> </span><span style="color: #E6EDF3">daily_revenue</span>
# MAGIC <span style="color: #FF7B72">AS</span><span style="color: #6E7681"> </span><span style="color: #FF7B72">SELECT</span><span style="color: #6E7681"> </span><span style="color: #E6EDF3">date(order_ts)</span><span style="color: #6E7681"> </span><span style="color: #FF7B72">AS</span><span style="color: #6E7681"> </span><span style="color: #E6EDF3">order_date,</span><span style="color: #6E7681"> </span><span style="color: #FF7B72">sum</span><span style="color: #E6EDF3">(amount)</span><span style="color: #6E7681"> </span><span style="color: #FF7B72">AS</span><span style="color: #6E7681"> </span><span style="color: #E6EDF3">revenue,</span><span style="color: #6E7681"> </span><span style="color: #FF7B72">count</span><span style="color: #E6EDF3">(</span><span style="color: #FF7B72; font-weight: bold">*</span><span style="color: #E6EDF3">)</span><span style="color: #6E7681"> </span><span style="color: #FF7B72">AS</span><span style="color: #6E7681"> </span><span style="color: #E6EDF3">orders</span>
# MAGIC <span style="color: #FF7B72">FROM</span><span style="color: #6E7681"> </span><span style="color: #E6EDF3">orders_silver</span>
# MAGIC <span style="color: #FF7B72">GROUP</span><span style="color: #6E7681"> </span><span style="color: #FF7B72">BY</span><span style="color: #6E7681"> </span><span style="color: #FF7B72">ALL</span><span style="color: #E6EDF3">;</span></pre></div>
